type MessageKey = keyof typeof messages.en | keyof typeof supplementalMessages.en
function getMessage(locale: Locale, key: MessageKey): string {
  const supplemental = supplementalMessages[locale] as Partial<Record<MessageKey, string>>
  const base = messages[locale] as Partial<Record<MessageKey, string>>
  return supplemental[key] ?? base[key] ?? key
}
const I18nContext = createContext<{ locale: Locale; t: (key: MessageKey) => string }>({ locale: "en", t: (key) => getMessage("en", key) })

export function I18nProvider({ locale, children }: { locale: Locale; children: React.ReactNode }) {
  const value = useMemo(() => ({ locale, t: (key: MessageKey) => getMessage(locale, key) }), [locale])
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

export function useI18n() {
  return useContext(I18nContext)
}

export function localizeDictionaryText(value: React.ReactNode, locale: Locale): React.ReactNode {
  if (locale !== "it" || typeof value !== "string") return value
  const key = ([...Object.keys(messages.en), ...Object.keys(supplementalMessages.en)] as MessageKey[]).find((candidate) => getMessage("en", candidate) === value)
  return key ? getMessage("it", key) : value
}

export function localizeRoleName(roleKey: string | null | undefined, name: string, locale: Locale) {
  if (locale !== "it") return name
  const key =
    roleKey === "owner" ? "roleOwnerName" :
    roleKey === "admin" ? "roleAdminName" :
    roleKey === "member" ? "roleMemberName" :
    roleKey === "guest" ? "roleGuestName" : null
  return key ? messages.it[key] : name
}

